        lockNames.slice(0, 18).forEach(function (ln) { h.push('<tr><td><a href="#/locks/' + encodeURIComponent(ln) + '"><code>' + esc(ln) + "</code></a></td><td>" + lockUse[ln][0] + "</td><td>" + lockUse[ln][1] + "</td><td><code>" + esc(X.locks[ln].ex[0] || "") + "</code></td></tr>"); });
        h.push("</tbody></table></div>");
